import { Component, Input, Output, EventEmitter } from "@angular/core";
import { CommonModule } from "@angular/common";
import { Router } from "@angular/router";
import { FormsModule } from "@angular/forms";

@Component({
  selector: "app-calculadora-modal",
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  templateUrl: "./calculadora-modal.component.html",
  styleUrls: ["./calculadora-modal.component.scss"],
})
export class CalculadoraModalComponent {
  @Input() visible = false;
  @Output() visibleChange = new EventEmitter<boolean>();

  // Inputs for calculation
  electricityKwhPerMonth = 0;
  carKmPerYear = 0;
  flightHoursPerYear = 0;
  dietType = 'omnivore'; // omnivore, vegetarian, vegan

  // Results
  resultado = 0;
  feedback = "";
  cor = "";

  constructor(private router: Router) {}

  calcular() {
    // Calculate CO2 emissions (simplified factors for educational purposes)
    const electricityEmission = this.electricityKwhPerMonth * 12 * 0.0005; // kWh/year * 0.0005 tCO2/kWh
    const carEmission = this.carKmPerYear * 0.0002; // km/year * 0.0002 tCO2/km
    const flightEmission = this.flightHoursPerYear * 0.2; // hours/year * 0.2 tCO2/hour

    let dietEmission = 0;
    switch (this.dietType) {
      case 'omnivore':
        dietEmission = 2.0;
        break;
      case 'vegetarian':
        dietEmission = 1.0;
        break;
      case 'vegan':
        dietEmission = 0.5;
        break;
    }

    this.resultado = electricityEmission + carEmission + flightEmission + dietEmission;
    this.setFeedback();
  }

  setFeedback() {
    if (this.resultado < 1) {
      this.feedback = "PARABÉNS!";
      this.cor = "#00a86b";
    } else if (this.resultado < 2) {
      this.feedback = "ÓTIMO!";
      this.cor = "#7cb342";
    } else if (this.resultado < 4) {
      this.feedback = "MÉDIA";
      this.cor = "#fbc02d";
    } else if (this.resultado < 6) {
      this.feedback = "ALERTA";
      this.cor = "#f57c00";
    } else {
      this.feedback = "CRÍTICO";
      this.cor = "#d32f2f";
    }
  }

  fechar() {
    this.visible = false;
    this.visibleChange.emit(this.visible);
  }

  verAcoes() {
    this.fechar();
    this.router.navigate(["/acoes"]);
  }
}
